// CSD_RATIONALE_BEGIN
// Root-cause analysis of the 79.6% → ?% syntax gap:
// Dominant failure mode is the model writing {curly_brace} variable notation
// (e.g., `{n} * {price}`) inside << >> spans.  The parser rejects any token
// that includes `{` or `}`, so those spans become syntax-invalid.
// Secondary failure: missing int() wrapper on integer-count expressions.
//
// Correct_with_activity = 0 across all attempts confirms that hard constrained
// intervention consistently hurts accuracy.  The model's *free* generation path
// produces the right math more often than the constrained path.
//
// Strategy: keep the best-performing structure (GenerateWithPrefixAndManagedSpan
// at 78% prefix budget) and make one targeted change — substantially improve the
// guidance block so the model understands that {var} in the problem statement
// must become var (no braces) in the << >> expression.
// Lower boostAmount to 6.0 and raise narrowThreshold to 10 to reduce the
// frequency of constrained-path intervention while retaining span lifecycle
// management (open detection, forced open at prefixBudget, close-when-complete).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Initialization sets insideConstrainedOut := insideConstrained and
//   currentConstrainedOut := currentConstrained, which satisfy the invariant by
//   the method precondition.  GenerateWithPrefixAndManagedSpan's postcondition
//   directly guarantees both the closed branch (!inside ==> current == []) and
//   the open branch (inside ==> parser.IsValidPrefix(current)).  No code path
//   after the helper modifies these variables, so the invariant holds at return.
//
// progress: |generated| <= |generatedPrefix| + maxSteps, cost <= maxSteps
//   GenerateWithPrefixAndManagedSpan postcondition guarantees
//   |generated| <= |generatedPrefix| + maxSteps.  We assign cost := maxSteps,
//   satisfying cost <= maxSteps.  When maxSteps > 0 the helper consumes at
//   least one token-step (it either generates a free token, forces OpenConstrainedSpan,
//   or closes a span), so cost = maxSteps > 0 satisfies the liveness clause.
//   Visible span growth is bounded by consumed token budget: every token
//   appended to generated costs one step from the maxSteps budget, and the
//   helper never appends more tokens than it consumes steps.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  // Targeted guidance: explicitly teach the model that {var} in the problem
  // statement must become var (no braces) inside << >>.
  var guidance: string :=
    "Solve this symbolic math word problem step by step.\n\n" +
    "The problem statement marks template variable names with curly braces: " +
    "{n}, {price}, {total}, {frac}, {frac_1}, etc.\n\n" +
    "TRANSLATION RULE: Inside << >>, drop the curly braces entirely.\n" +
    "  {n}      -> n\n" +
    "  {price}  -> price\n" +
    "  {total}  -> total\n" +
    "  {frac_1} -> frac_1\n" +
    "Never include { or } inside << >>.\n\n" +
    "FINAL ANSWER: Write exactly ONE <<expression>> at the very end.\n" +
    "Allowed inside << >>: plain variable names (no braces), integers, " +
    "+, -, *, /, //, %, (, ), int()\n" +
    "Use int() when the answer is a whole-number count or amount.\n\n" +
    "Correct examples:\n" +
    "  <<int(n * price)>>\n" +
    "  <<int(total - 2 * n - m)>>\n" +
    "  <<n - int(n * frac)>>\n" +
    "  <<int(x * k * (12 // period))>>\n" +
    "  <<int(n1 + n1 * p / 100)>>\n\n" +
    "Forbidden: {braces}, LaTeX ($...$, \\times), ** operator, multiple spans.";

  helpers.AppendTaskGuidance(lm, guidance);

  var prefixBudget: nat := (maxSteps * 78) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, 6.0, 10, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

